sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var rows = api.state.inquiry_info;
    var test = [];
    var arr = [];
    const keys = Object.keys(rows);

    keys.forEach(function(key) {
        var meisai_num = rows[key].cells.number.metadata.openRecordMetadata.sysId;

        if(arr.indexOf(meisai_num) === -1) {
            arr.push(meisai_num);
        };
    });
    test.records = arr.join(',');
        api.data.inquiry_info_1.execute(test);
}
